'use strict';
const $=s=>document.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const link=(path,text,cls='')=>`<a class="${cls}" href="#${esc(path)}">${text}</a>`;
const departments=[
 ['ディレクター','大会全体の準備・振り返り'],['トーナメント','競技進行・卓配置'],['メディア','撮影・取材・発信'],['カスタマー','受付・問い合わせ対応'],['クリエイティブ','バナー・制作物'],['ロジスティックス','備品・搬入出'],['マーケティング','告知・キャンペーン'],['営業','協賛・出展準備'],['インフルエンサー','出演・投稿連携'],['その他','部署共通の資料・手続き']
];
const brands=['JOPT','SPADIE','戦国','U-30'];
const projectSeeds=[
 [0,'大会準備・引き継ぎ','担当間の準備事項と、当日判断に必要な資料を確認する。','当日進行チェック','大会運営方針','担当・連絡先一覧','check'],
 [0,'大会の振り返り','開催後の気づきと次回へ引き継ぐ改善点をまとめる。','改善項目の整理','振り返り会議資料','改善事項一覧','check'],
 [1,'チーム戦の卓配置','3on3・2on2のチーム数から、必要な卓数を確認する。','3on3・2on2卓数計算','チーム戦運営メモ','エントリーチーム一覧','table'],
 [1,'競技開始の準備','進行確認・アナウンス・卓配置をひとつの業務から参照する。','開始前チェック','競技進行マニュアル','卓配置一覧','check'],
 [2,'撮影・投稿','撮影から写真の選定、投稿前確認までの資料をまとめる。','投稿前チェック','撮影・投稿前チェックマニュアル','撮影カット一覧','check'],
 [2,'インタビュー制作','取材メモ、原稿、公開前の確認事項をまとめて管理する。','インタビューメモ整理','取材・原稿作成手順','取材対象・日程一覧','notes'],
 [3,'ミッションチャレンジ','運用ルール、参加状況、Voucher付与の確認に必要な資料をまとめる。','Voucher付与数の確認','ミッション運用ルール','参加・付与管理シート','voucher'],
 [3,'スタッフ参赛受付','参加条件の確認と、受付担当の引き継ぎに使用する。','スタッフ参加確認','スタッフ受付手順','受付対応一覧','check'],
 [4,'スタートバナー制作','大会名と競技名を指定して、開始告知の見え方を確認する。','スタートバナープレビュー','バナー制作仕様','制作サイズ一覧','banner'],
 [4,'物販カラー検討','カードプロテクターの配色と、制作前の確認資料をまとめる。','カラープレビュー','物販制作メモ','カラー候補一覧','color'],
 [5,'会場搬入・撤収','備品の数量確認から搬入・撤収の引き継ぎまでをまとめる。','搬入チェック','会場搬入出手順','備品・数量一覧','check'],
 [5,'備品の貸出・返却','会場で使用する備品の持ち出しと返却を確認する。','返却チェック','備品貸出ルール','貸出・返却記録','check'],
 [6,'告知スケジュール','大会ごとの告知日程と、投稿に必要な素材を確認する。','告知予定プレビュー','告知運用メモ','告知スケジュール表','schedule'],
 [6,'キャンペーン運用','対象・実施期間・告知内容を同じ業務の資料として参照する。','実施前チェック','キャンペーン企画書','実施条件一覧','check'],
 [7,'協賛提案','提案先に合わせた資料と、提供内容の確認に使用する。','提案準備チェック','協賛提案の構成例','提供メニュー一覧','check'],
 [7,'出展の準備','出展者向けの案内、設置要件、当日の対応事項を確認する。','出展準備チェック','出展準備の案内','設置・必要備品一覧','check'],
 [8,'出演・投稿連携','出演日程と投稿素材、公開前確認をまとめて参照する。','出演前チェック','出演・投稿確認メモ','出演スケジュール','check'],
 [8,'投稿素材の共有','投稿する際の素材と表記条件を確認する。','表記チェック','投稿時の表記例','素材受け渡し一覧','check'],
 [9,'社内資料の共有','社内で使う資料の登録方法と、共有範囲を確認する。','登録前チェック','資料登録の手順','共有範囲の確認表','check'],
 [9,'議事録・引き継ぎ','会議の決定事項と引き継ぐ作業を整理する。','議事録メモ整理','引き継ぎ記入例','引き継ぎ項目一覧','notes']
];
const references={2:['3on3、2on2計算アプリ','7d5508be-a632-427a-a181-a832d01494e3'],4:['JOPT メディア撮影・投稿前チェックマニュアル','590f7768-fd91-4b73-8afa-19b396ac0f51'],5:['Interview Studio','71000a01-9826-4b6f-8c9c-0d825041d156'],7:['スタッフ専用トーナメント参加確認受付（青色版）','a94b16ac-f772-400b-9371-f93bd0ae4138'],8:['JOPTスタートバナーツール','541aa9c4-585a-4dd6-b56c-ed5c15afe61d'],9:['物販カラーシミュレーター','1ee1aa7d-4e9d-473d-b220-98de89c011a6'],12:['マーケスケジュール管理','c4fd3ff7-b02d-4fe9-b21c-772510aab2c9']};
const editions=brands.flatMap((b,i)=>[{id:`e${i}-0`,brand:b,name:`${b} Tokyo 2026 #03`},{id:`e${i}-1`,brand:b,name:`${b} Osaka 2026 #02`}]);
const projects=projectSeeds.map((s,n)=>({id:'p'+n,dept:s[0],title:s[1].replace('参赛','参加'),description:s[2],tool:s[3],doc:s[4],sheet:s[5],demo:s[6],edition:`e${n%4}-${Math.floor(n/4)%2}`,reference:references[n]}));
const resources=projects.flatMap((p,n)=>[
 {id:`${p.id}-app`,project:p.id,title:p.tool,type:'ツール',description:p.description,demo:p.demo},
 {id:`${p.id}-doc`,project:p.id,title:p.doc,type:'資料',description:`${p.title}の目的・確認事項・担当間の引き継ぎを確認する。`},
 {id:`${p.id}-sheet`,project:p.id,title:p.sheet,type:'管理表',description:`${p.title}に必要な項目を、一覧で確認する。`}
].map((r,k)=>({...r,section:departments[p.dept][0],date:'2026.11.'+String(16-(n%6)).padStart(2,'0'),mine:n%5===0,tags:[p.title,brands[n%4],n===6?'Voucher':n===7?'Ticket':'業務'],visibility:'all'})));
const news=[
 {id:'n1',title:'資料探しからAI活用へ。業務単位で情報をまとめるには',date:'2026.11.16',summary:'企画書、管理表、ツールを同じ業務から参照する使い方。',paragraphs:['仕事で必要になるのは、ツールだけとは限りません。運用ルールを読み、管理表を確認し、必要に応じてツールを使う。一つの業務に複数の資料が関係します。','例えばミッションチャレンジなら、運用ルール、参加状況の管理表、Voucher付与の確認ツールをまとめて参照できます。','ポータルでは、検索または部署・大会のページから業務を選び、関連する資料へ進む使い方を想定しています。']},
 {id:'n2',title:'Codexで資料を探すときに、最新ニュースも受け取る',date:'2026.11.15',summary:'ポータルを開かずに情報を受け取る連携の表示例。',paragraphs:['Codexからポータルの資料を取得する場面で、最新のAIニュースもあわせて受け取る仕組みを想定しています。','資料の検索結果と、記事のタイトル・日付・リンクを同じ応答に含めることで、普段の業務の中に情報を届けます。','この原型では連携の見え方を確認できます。実際のニュース取得やMCP接続は行っていません。']},
 {id:'n3',title:'画像制作の前に、バナーの見え方を試す',date:'2026.11.14',summary:'タイトルや大会名を入れ替えて、制作イメージを共有する。',paragraphs:['大会名や競技名を入れたバナーの見え方を先に確認すると、制作担当と依頼側で文字量や配置を相談できます。','クリエイティブの「スタートバナー制作」から、関連するツールや制作資料を確認できる構成を想定しています。','確認用プレビューのため、正式なロゴや入稿仕様を再現したものではありません。']},
 {id:'n4',title:'議事録を共有する前に、決定事項と次の作業を分ける',date:'2026.11.13',summary:'会議の内容を引き継ぎやすくする整理方法。',paragraphs:['会議の発言を残すだけでなく、決まったこと、担当者、次に行う作業を分けると、後から確認しやすくなります。','「議事録・引き継ぎ」には、関連するツールと資料の入口をまとめています。','AIによる意味の分類は実装していません。画面の遷移と入力の流れを確認するデモです。']}
];
let items=[...resources],saved=new Set(['p6-app','p4-doc']),mode='link',timer;
try{const s=JSON.parse(sessionStorage.getItem('portal-pages-v1'));if(s){saved=new Set(s.saved||[]);items.push(...(s.added||[]).filter(i=>i&&typeof i.id==='string'&&typeof i.title==='string'));}}catch{}
function persist(){try{sessionStorage.setItem('portal-pages-v1',JSON.stringify({saved:[...saved],added:items.filter(i=>i.id.startsWith('user-'))}));}catch{}}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(timer);timer=setTimeout(()=>$('#toast').classList.remove('show'),3000);}
function route(){const raw=location.hash.slice(1)||'/';const i=raw.indexOf('?');const path=(i<0?raw:raw.slice(0,i)).split('/').filter(Boolean).map(decodeURIComponent);return {path,params:new URLSearchParams(i<0?'':raw.slice(i+1))};}
function go(p){if(location.hash==='#'+p)render();else location.hash=p;}
function crumb(parts=[]){return `<nav class="breadcrumbs" aria-label="パンくず">${link('/','ホーム')}${parts.map(([name,path])=>`<span>›</span>${path?link(path,esc(name)):`<span aria-current="page">${esc(name)}</span>`}`).join('')}</nav>`;}
function title(t,desc='',parts=[]){return `${crumb([...parts,[t]])}<div class="page-title"><h1>${esc(t)}</h1>${desc?`<p>${esc(desc)}</p>`:''}</div>`;}
function projectCard(p){const e=editions.find(e=>e.id===p.edition);return link('/business/'+p.id,`<small>${esc(departments[p.dept][0])} · ${items.filter(i=>i.project===p.id).length}件</small><h2>${esc(p.title)}</h2><p>${esc(p.description)}</p><span class="card-end">${esc(e.name)}<b>→</b></span>`,'business-card');}
function searchForm(q='',compact=false){return `<form class="page-search ${compact?'compact':''}" role="search"><button aria-label="検索" type="submit">⌕</button><input name="q" type="search" aria-label="資料・ツールを検索" placeholder="業務名・資料・キーワードで検索" value="${esc(q)}"><button type="submit" class="search-submit">検索</button></form>`;}
function newsRow(n){return link('/news/'+n.id,`<span>${esc(n.title)}</span><small>${n.date} ↗</small>`,'news-row');}
function rows(list){return list.length?`<div class="table-wrap"><table class="resource-table"><thead><tr><th>資料・ツール</th><th>用途・関連業務</th><th>操作</th></tr></thead><tbody>${list.map(i=>{const p=projects.find(p=>p.id===i.project);return `<tr><td>${link('/resource/'+i.id,`<span class="type-label">${esc(i.type)}</span>${esc(i.title)}`,'resource-main')}</td><td>${esc(i.description)}${p?`<small>${link('/business/'+p.id,esc(p.title))}</small>`:''}</td><td><div class="row-actions">${link('/resource/'+i.id, '詳細 →')}<button data-save="${esc(i.id)}" aria-label="${esc(i.title)}を${saved.has(i.id)?'保存済みから外す':'保存する'}" aria-pressed="${saved.has(i.id)}">${saved.has(i.id)?'▣':'▢'}</button></div></td></tr>`;}).join('')}</tbody></table></div>`:`<div class="empty"><h2>該当する資料がありません</h2><p>検索条件を変えるか、部署から探してください。</p>${link('/','ホームへ戻る →')}</div>`;}
const pickupExamples=[
 [{id:'p6',label:'大会前に確認',title:'ミッションチャレンジの受付・運用ルール',note:'運用ルール、管理表、関連ツールを確認。'},
  {id:'p4',label:'ほかの部署から',title:'メディアの撮影・投稿チェック',note:'撮影から投稿までの手順をまとめて確認。'},
  {id:'p8',label:'ツールを探す',title:'スタートバナー制作のツール・資料',note:'バナー制作に使うツールと仕様を確認。'}],
 [{id:'p10',label:'大会前に確認',title:'会場搬入の準備を確認する',note:'搬入手順、備品一覧、チェック項目を確認。'},
  {id:'p12',label:'ほかの部署から',title:'マーケティングの告知スケジュール',note:'告知予定と、運用に使う資料を確認。'},
  {id:'p2',label:'ツールを探す',title:'チーム戦の卓配置を確認する',note:'卓配置に使うツールと運営資料を確認。'}],
 [{id:'p14',label:'ほかの部署から',title:'営業の協賛提案準備',note:'提案資料と、提供内容の一覧を確認。'},
  {id:'p16',label:'大会前に確認',title:'出演・投稿の準備を確認する',note:'出演予定と、投稿前に確認する資料を見る。'},
  {id:'p9',label:'ツールを探す',title:'物販カラー検討のツール・資料',note:'配色検討に使うツールと制作資料を確認。'}]
];
let pickupExample=0;
function pickup(){return `<section class="pickup" aria-labelledby="pickup-title"><div class="section-label"><h2 id="pickup-title">PICK UP <small>ほかの部署の業務・ツール</small></h2><button id="pickup-next" type="button" aria-label="PICK UPの別の表示例を見る">ほかの例を見る ↻</button></div><div class="pickup-grid" id="pickup-items">${pickupExamples[pickupExample].map(c=>{const p=projects.find(p=>p.id===c.id);return link('/business/'+c.id,`<span class="pickup-label">${esc(c.label)}</span><h3>${esc(c.title)}</h3><p>${esc(c.note)}</p><span class="pickup-end">${esc(departments[p.dept][0])}<b>→</b></span>`,'pickup-card');}).join('')}</div><small class="demo-note">おすすめ表示のサンプルです</small></section>`;}
function home(){return `<section class="hero"><h1>何をお探しですか？</h1>${searchForm()}<div class="tags">${['Voucher','Ticket','バナー'].map(t=>link('/search?q='+encodeURIComponent(t),esc(t))).join('')}</div><div class="browse-links">${link('/sections','セクションから探す →')}${link('/events','大会から探す →')}</div></section>${pickup()}<section class="news" aria-labelledby="news-title"><div class="section-label"><h2 id="news-title">AIニュース</h2>${link('/news','すべて見る →')}</div>${news.slice(0,2).map(newsRow).join('')}<small class="demo-note">架空の記事 · 表示例</small></section>`;}

function listPage(kind,params){let q=params.get('q')||'',dept=params.get('section')||'',type=params.get('type')||'';let list=items.filter(i=>(kind!=='mine'||i.mine)&&(kind!=='saved'||saved.has(i.id))&&(!dept||i.section===dept)&&(!type||i.type===type)&&(!q||[i.title,i.description,...i.tags,i.section,projects.find(p=>p.id===i.project)?.title||''].join(' ').toLocaleLowerCase('ja').includes(q.toLocaleLowerCase('ja'))));list.sort(params.get('sort')==='name'?(a,b)=>a.title.localeCompare(b.title,'ja'):(a,b)=>b.date.localeCompare(a.date)||a.title.localeCompare(b.title,'ja'));const h={mine:'自分の資料',saved:'保存済み',search:'検索結果',library:'資料・ツール'}[kind];const matchedProjects=q?projects.filter(p=>[p.title,p.description].join(' ').toLowerCase().includes(q.toLowerCase())):[];return `${title(h,kind==='search'?`「${q}」に関連する資料を表示しています。`:'用途を確認して、必要な資料やツールを開けます。')}${searchForm(q,true)}<form id="list-filter" class="list-filter"><label>セクション<select name="section"><option value="">すべて</option>${departments.map(([n])=>`<option ${n===dept?'selected':''}>${n}</option>`).join('')}</select></label><label>種類<select name="type"><option value="">すべて</option>${['ツール','資料','管理表','リンク','HTML'].map(t=>`<option ${t===type?'selected':''}>${t}</option>`).join('')}</select></label><label>並び順<select name="sort"><option value="updated">更新順</option><option value="name" ${params.get('sort')==='name'?'selected':''}>名前順</option></select></label><span>${list.length}件</span></form>${matchedProjects.length?`<h2 class="section-label">関連する業務</h2><div class="business-grid">${matchedProjects.map(projectCard).join('')}</div><h2 class="section-label">資料・ツール</h2>`:''}${rows(list)}`;}
function business(p){const dept=departments[p.dept][0];const list=items.filter(i=>i.project===p.id);const e=editions.find(e=>e.id===p.edition);return `${title(p.title,p.description,[[dept,'/section/'+p.dept]])}<div class="business-meta">${link('/edition/'+p.edition,esc(e.name))}<span>画面確認用の架空業務</span></div><h2 class="section-label">この業務で使う資料・ツール</h2>${rows(list)}<div class="business-bottom">${link('/section/'+p.dept,esc(dept)+'の他の業務を見る →')}</div>`;}
function resourcePage(i){const p=projects.find(p=>p.id===i.project);return `${title(i.title,i.description,p?[[departments[p.dept][0],'/section/'+p.dept],[p.title,'/business/'+p.id]]:[])}<div class="detail-panel"><div class="detail-top"><span class="type-label">${esc(i.type)}</span><button class="secondary" data-save="${esc(i.id)}">${saved.has(i.id)?'▣ 保存済み':'▢ 保存する'}</button></div><dl class="metadata"><dt>セクション</dt><dd>${link('/section/'+Math.max(0,departments.findIndex(([d])=>d===i.section)),esc(i.section))}</dd><dt>更新日</dt><dd>${esc(i.date)}</dd><dt>共有範囲</dt><dd>${i.visibility==='limited'?'指定アカウントのみ':'JOPT全社'}</dd><dt>タグ</dt><dd>${i.tags.map(t=>link('/search?q='+encodeURIComponent(t),esc(t),'tag')).join('')}</dd></dl><div class="detail-actions">${i.type==='ツール'?`<button class="primary" data-open-tool="${esc(i.id)}">ツールを開く ↗</button>`:link('/preview/'+i.id,'資料を開く →','primary')}${p?link('/business/'+p.id,'関連する業務を見る','secondary'):''}</div><p class="demo-note">この資料と内容はデモ用です。実データ・原本には接続していません。</p>${p?.reference?`<p class="reference">題材参考：AIFACT「${esc(p.reference[0])}」。内容・関連業務は本デモ用に再構成しています。</p>`:''}</div>`;}
function previewPage(i){const p=projects.find(p=>p.id===i.project);let content='';if(i.type==='ツール')return resourcePage(i);if(i.type==='管理表')content=`<table class="preview-table"><thead><tr><th>項目</th><th>内容</th><th>状態</th></tr></thead><tbody>${['対象・条件','必要資料','実施準備','完了後の確認'].map((t,n)=>`<tr><td>${t}</td><td>${esc(p?.title||i.title)}：${['確認対象を一覧化','関連する資料を用意','担当間で事前確認','記録と引き継ぎ'][n]}</td><td>${n<2?'確認済み':'確認待ち'}</td></tr>`).join('')}</tbody></table>`;else content=`<article class="document-demo"><h2>目的</h2><p>${esc(i.description)}</p><h2>確認すること</h2><ol><li>対象となる大会・実施条件を確認する。</li><li>関連する管理表とツールを開き、必要項目を整理する。</li><li>作業結果を記録し、次の担当へ引き継ぐ。</li></ol><h2>関連資料</h2><p>${p?link('/business/'+p.id,esc(p.title)+'の資料一覧 →'):'登録したリンク・ファイルの原本は、このデモには保存されていません。'}</p></article>`;return `${title(i.title,'画面確認用サンプル。入力内容は外部へ送信されません。',[[i.title+'の詳細','/resource/'+i.id]])}<div class="demo-surface"><span class="demo-badge">デモ専用 · 実業務には使用しないでください</span>${content}</div>`;}
function newsPage(n){return `${title(n.title,n.summary,[['AIニュース','/news']])}<article class="article"><div class="article-meta">${n.date} · デモ編集部 · 架空記事</div>${n.paragraphs.map(p=>`<p>${esc(p)}</p>`).join('')}<div class="notice">画面確認のために作成した記事です。実際の報道・社内決定事項ではありません。</div><p>${link('/news','ニュース一覧に戻る →')}</p></article>`;}
function render(){const {path,params}=route();let [kind,id]=path;if(kind==='preview'&&items.some(i=>i.id===id&&i.type==='ツール')){kind='resource';history.replaceState(null,'','#/resource/'+encodeURIComponent(id));}let html;document.body.classList.toggle('subpage',!!kind);document.querySelectorAll('[data-nav]').forEach(a=>{const on=a.dataset.nav===(kind||'home');a.classList.toggle('active',on);if(on)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});
 if(!kind)html=home();
 else if(['library','search','mine','saved'].includes(kind))html=listPage(kind,params);
 else if(kind==='sections')html=`${title('セクションから探す','部署を選んで、業務ごとの資料へ進めます。')}<div class="directory">${departments.map(([name,desc],i)=>link('/section/'+i,`<span><strong>${esc(name)}</strong><small>${esc(desc)}</small></span><span>→</span>`)).join('')}</div>`;
 else if(kind==='events')html=`${title('大会から探す','大会を選び、開催回ごとの資料へ進めます。')}<div class="directory">${brands.map(b=>link('/event/'+encodeURIComponent(b),`<strong>${esc(b)}</strong><span>→</span>`)).join('')}</div>`;
 else if(kind==='section'&&departments[Number(id)]){const n=Number(id);html=`${title(departments[n][0],departments[n][1],[['セクション','/sections']])}<h2 class="section-label">業務・プロジェクトから選ぶ</h2><div class="business-grid">${projects.filter(p=>p.dept===n).map(projectCard).join('')}</div>`;}
 else if(kind==='event'&&brands.includes(id))html=`${title(id,'開催回を選んで、関連する業務と資料を確認できます。',[['大会','/events']])}<div class="business-grid">${editions.filter(e=>e.brand===id).map(e=>link('/edition/'+e.id,`<small>開催回 · 表示例</small><h2>${esc(e.name)}</h2><p>関連する業務・資料を見る</p><span class="card-end">${projects.filter(p=>p.edition===e.id).length}業務<b>→</b></span>`,'business-card')).join('')}</div><p class="demo-note">開催回の名称・紐付けはデモ用です。</p>`;
 else if(kind==='edition'&&editions.some(e=>e.id===id)){const e=editions.find(e=>e.id===id);html=`${title(e.name,'この開催回で使う業務・資料の表示例です。',[[e.brand,'/event/'+e.brand]])}<div class="business-grid">${projects.filter(p=>p.edition===id).map(projectCard).join('')}</div>`;}
 else if(kind==='business'&&projects.some(p=>p.id===id))html=business(projects.find(p=>p.id===id));
 else if(kind==='resource'&&items.some(i=>i.id===id))html=resourcePage(items.find(i=>i.id===id));
 else if(kind==='preview'&&items.some(i=>i.id===id))html=previewPage(items.find(i=>i.id===id));
 else if(kind==='news'&&!id)html=`${title('AIニュース','業務に関連するAIの話題を読む。以下はすべて架空の記事です。')}<div class="news-list">${news.map(n=>link('/news/'+n.id,`<small>${n.date} · 架空記事</small><h2>${esc(n.title)}</h2><p>${esc(n.summary)}</p><span>記事を読む →</span>`,'news-card')).join('')}</div>`;
 else if(kind==='news'&&news.some(n=>n.id===id))html=newsPage(news.find(n=>n.id===id));
 else html=`${title('ページが見つかりません')}<p>${link('/','ホームへ戻る →')}</p>`;
 $('#page').innerHTML=html;document.title=($('#page h1')?.textContent||'ホーム')+'｜業務ポータル';}
function openInfo(h,body){$('#info-content').innerHTML=`<div class="modal-top"><h2>${esc(h)}</h2><button class="close" aria-label="閉じる">×</button></div>${body}`;$('#info-dialog').showModal();}
function codex(){openInfo('Codexと連携',`<p class="modal-description">資料と最新AIニュースを同時に受け取る表示例です。</p><div class="notice">MCP・Codexは未接続です。</div><div class="code-preview"><strong>あなた</strong><p>ミッションチャレンジの運用資料を探して</p></div><div class="code-preview"><strong>Codexの応答例</strong><p>${link('/business/p6','ミッションチャレンジ →')}</p><ul><li>ミッション運用ルール</li><li>参加・付与管理シート</li><li>Voucher付与数の確認</li></ul><hr><strong>最新AIニュース（デモ）</strong><p>${link('/news/n1',esc(news[0].title))}</p><p>${link('/news/n2',esc(news[1].title))}</p></div>`);}
$('#codex').onclick=codex;$('#account').onclick=()=>openInfo('Googleアカウントでログイン','<p class="modal-description">正式版では会社のGoogleアカウントでログインします。</p><div class="notice">この原型はデモユーザーとして利用できます。Google認証は未接続です。</div>');
function setMode(m){mode=m;document.querySelectorAll('[data-mode]').forEach(b=>b.classList.toggle('selected',b.dataset.mode===m));$('#url-field').hidden=m!=='link';$('#file-field').hidden=m!=='html';const f=$('#registration');f.elements.url.required=m==='link';f.elements.url.disabled=m!=='link';f.elements.file.required=m==='html';f.elements.file.disabled=m!=='html';}
$('#register').onclick=()=>$('#register-dialog').showModal();document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>setMode(b.dataset.mode));$('#visibility').onchange=()=>{const on=$('#visibility').value==='limited';$('#recipients-field').hidden=!on;$('#registration').elements.recipients.required=on;};
$('#registration').onsubmit=e=>{e.preventDefault();const f=e.target;if(!f.reportValidity())return;const t=f.elements.title.value.trim();if(!t){f.elements.title.setCustomValidity('タイトルを入力してください');f.elements.title.reportValidity();return;}if(mode==='link'&&!/^https?:\/\//i.test(f.elements.url.value)){f.elements.url.setCustomValidity('http:// または https:// のURLを入力してください');f.elements.url.reportValidity();return;}if(mode==='html'&&!/\.html?$/i.test(f.elements.file.files[0]?.name||'')){toast('HTMLファイルを選んでください');return;}const d=departments.findIndex(([s])=>s===f.elements.section.value);const date=new Intl.DateTimeFormat('ja-JP',{timeZone:'Asia/Tokyo',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date()).replaceAll('/','.');const i={id:'user-'+Date.now(),project:projects.find(p=>p.dept===d)?.id,title:t,type:mode==='html'?'HTML':'リンク',description:f.elements.description.value.trim()||'デモで登録した資料です。',section:f.elements.section.value,date,mine:true,tags:f.elements.tags.value.split(/[,，、]/).map(s=>s.trim()).filter(Boolean),visibility:f.elements.visibility.value};items.push(i);persist();f.reset();$('#recipients-field').hidden=true;f.elements.recipients.required=false;setMode('link');$('#register-dialog').close();go('/resource/'+i.id);toast('デモ内に登録しました。外部への保存は行っていません。');};
$('#registration').addEventListener('input',e=>e.target.setCustomValidity?.(''));
function applyFilters(){const {path,params}=route();const f=$('#list-filter');for(const n of ['section','type','sort']){const v=f.elements[n].value;if(v)params.set(n,v);else params.delete(n);}go('/'+path[0]+'?'+params.toString());}
$('#page').addEventListener('change',e=>{if(e.target.closest('#list-filter'))applyFilters();});
$('#page').addEventListener('submit',e=>{e.preventDefault();const f=e.target;if(!f.reportValidity())return;if(f.classList.contains('page-search'))go('/search?q='+encodeURIComponent(f.elements.q.value.trim()));});
 document.addEventListener('click',e=>{const b=e.target.closest('button');if(b?.dataset.openTool){const i=items.find(i=>i.id===b.dataset.openTool);if(i)openInfo('外部ツールを開く',`<p class="modal-description">${esc(i.title)}</p><div class="notice">正式版では登録された外部ツールを開きます。この画面サンプルではリンク先に接続していません。</div>`);}if(b?.id==='pickup-next'){pickupExample=(pickupExample+1)%pickupExamples.length;const el=document.querySelector('.pickup');el.outerHTML=pickup();document.querySelector('#pickup-next').focus();}if(b?.classList.contains('close'))b.closest('dialog').close();if(b?.dataset.save){saved.has(b.dataset.save)?saved.delete(b.dataset.save):saved.add(b.dataset.save);persist();render();toast('保存済みを更新しました');}if(e.target.closest('a[href^="#/"]'))document.querySelectorAll('dialog[open]').forEach(d=>d.close());});
window.addEventListener('hashchange',()=>{document.querySelectorAll('dialog[open]').forEach(d=>d.close());render();window.scrollTo(0,0);});
document.addEventListener('keydown',e=>{if(e.key==='/'&&!document.querySelector('dialog[open]')&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)){const input=$('.page-search input');if(input){e.preventDefault();input.focus();}}});
render();setMode('link');
